'use server'

import { revalidatePath } from 'next/cache'
import { getNotificationPreference, setNotificationPreference } from '@/lib/notifications'

export async function toggleNotificationPreference() {
  const current = await getNotificationPreference()
  await setNotificationPreference(!current)

  // Re-render the current route on the server without navigating away.
  revalidatePath('/')
}

